import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    book = {}  # id -> dict with side, price, qty, time, active
    time_counter = 0

    def clean_buy():
        while buy_heap:
            negp, t, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            p, t, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                p, t, sid = sell_heap[0]
                if typ != 'market' and price is not None and p > price:
                    break
                sinfo = book[sid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] <= 0:
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'time': time_counter, 'active': True}
                heapq.heappush(buy_heap, (-price, time_counter, oid))
                time_counter += 1
            else:
                # still register order in book for potential future reference (not needed, but to allow cancel of fully filled? no)
                time_counter += 1
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negp, t, bid = buy_heap[0]
                p = -negp
                if typ != 'market' and price is not None and p < price:
                    break
                binfo = book[bid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] <= 0:
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'time': time_counter, 'active': True}
                heapq.heappush(sell_heap, (price, time_counter, oid))
                time_counter += 1
            else:
                time_counter += 1

    return trades

